def lcs_length(s, t):
    # Longest Common Substring (contiguous)
    n, m = len(s), len(t)
    if n == 0 or m == 0:
        return 0

    # dp[j] = length of longest common substring ending at s[i-1] and t[j-1]
    dp = [0] * (m + 1)
    best = 0

    for i in range(1, n + 1):
        prev_diag = 0  # dp[j-1] from previous row (i-1)
        for j in range(1, m + 1):
            temp = dp[j]
            if s[i - 1] == t[j - 1]:
                dp[j] = prev_diag + 1
                if dp[j] > best:
                    best = dp[j]
            else:
                dp[j] = 0
            prev_diag = temp

    return best

