def levenshtein(source, target):
    # Correct base cases
    if source == '':
        return len(target)
    if target == '':
        return len(source)

    # If first characters match, no edit is needed for that position
    if source[0] == target[0]:
        return levenshtein(source[1:], target[1:])

    # Otherwise, consider insert, delete, substitute
    return 1 + min(
        levenshtein(source, target[1:]),     # insertion into source (or deletion from target)
        levenshtein(source[1:], target),     # deletion from source (or insertion into target)
        levenshtein(source[1:], target[1:]) # substitution
    )


