def lis(arr):
    # Patience sorting / tails array approach.
    # tails[k] = minimum possible tail value of an increasing subsequence of length k+1
    # For unique inputs, this yields the LIS length.
    tails = []
    for x in arr:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

